        "code": "# ===================================================================\n# Autonomous Agricultural Drone for Precision Fertilizer Spraying - IoT Telemetry & MQTT Bridge Service\n# ===================================================================\nfrom fastapi import FastAPI\nfrom fastapi.middleware.cors import CORSMiddleware\nfrom pydantic import BaseModel\nimport random\nimport time\n\napp = FastAPI(title=\"Autonomous Agricultural Drone for Precision Fertilizer Spraying - Telemetry Gateway\")\n\napp.add_middleware(\n    CORSMiddleware,\n    allow_origins=[\"*\"],\n    allow_methods=[\"*\"],\n    allow_headers=[\"*\"]\n)\n\nclass TelemetryPayload(BaseModel):\n    node_id: str = \"NODE-ESP32-01\"\n    sensor_reading: float\n    relay_status: bool\n    battery_level: float\n\nclass RelayTogglePayload(BaseModel):\n    state: bool = True\n\n@app.get(\"/api/telemetry/live\")\ndef get_live_telemetry():\n    val = round(random.uniform(22.0, 85.0), 2)\n    relay = val > 75.0\n    return {\n        \"project\": \"Autonomous Agricultural Drone for Precision Fertilizer Spraying\",\n        \"timestamp\": time.time(),\n        \"node_id\": \"NODE-ESP32-01\",\n        \"sensor_reading\": val,\n        \"unit\": \"PPM / \u00b0C / PSI\",\n        \"relay_active\": relay,\n        \"signal_strength\": \"-68 dBm (Strong)\",\n        \"status\": \"CRITICAL\" if relay else \"NORMAL\"\n    }\n\n@app.post(\"/api/actuator/toggle\")\ndef toggle_relay(payload: RelayTogglePayload = RelayTogglePayload()):\n    return {\"command\": \"RELAY_OVERRIDE\", \"new_state\": payload.state, \"acknowledged\": True}\n\nif __name__ == \"__main__\":\n    import uvicorn\n    uvicorn.run(app, host=\"127.0.0.1\", port=8000)\n"
