        "code": "# ===================================================================\n# Music Recommendation Engine with Collaborative Filtering - Data Analytics & Statistics Service\n# ===================================================================\nfrom fastapi import FastAPI\nfrom fastapi.middleware.cors import CORSMiddleware\nfrom pydantic import BaseModel\nimport pandas as pd\nimport numpy as np\n\napp = FastAPI(title=\"Music Recommendation Engine with Collaborative Filtering\")\n\napp.add_middleware(\n    CORSMiddleware,\n    allow_origins=[\"*\"],\n    allow_methods=[\"*\"],\n    allow_headers=[\"*\"]\n)\n\n# Simulated Dataset\ndf = pd.DataFrame({\n    \"CustomerID\": range(1001, 1011),\n    \"TransactionAmount\": [120.5, 450.0, 89.2, 1200.0, 310.5, 670.0, 95.0, 540.0, 890.0, 410.0],\n    \"Frequency\": [2, 8, 1, 15, 5, 9, 2, 7, 12, 6],\n    \"SatisfactionScore\": [4.5, 4.8, 3.2, 4.9, 4.1, 4.6, 3.8, 4.7, 4.9, 4.3]\n})\n\n@app.get(\"/api/data/summary\")\ndef get_summary():\n    return {\n        \"project\": \"Music Recommendation Engine with Collaborative Filtering\",\n        \"rows\": len(df),\n        \"columns\": list(df.columns),\n        \"mean_transaction\": float(df[\"TransactionAmount\"].mean()),\n        \"median_transaction\": float(df[\"TransactionAmount\"].median()),\n        \"std_dev\": float(df[\"TransactionAmount\"].std()),\n        \"correlation_amount_freq\": float(df[\"TransactionAmount\"].corr(df[\"Frequency\"]))\n    }\n\n@app.get(\"/api/data/records\")\ndef get_records():\n    return df.to_dict(orient=\"records\")\n\nif __name__ == \"__main__\":\n    import uvicorn\n    uvicorn.run(app, host=\"127.0.0.1\", port=8000)\n"
