        "code": "// ===================================================================\n// Decentralized Social Media Platform with Web3 Auth & IPFS - Express.js REST API Server\n// ===================================================================\nconst express = require('express');\nconst cors = require('cors');\n\nconst app = express();\napp.use(cors());\napp.use(express.json());\n\nlet items = [\n  { id: 1, title: \"Standard Package / Core Service\", price: 49.99, inStock: true },\n  { id: 2, title: \"Enterprise Tier / Cloud Module\", price: 149.99, inStock: true },\n  { id: 3, title: \"Custom Integration Extension\", price: 89.99, inStock: true }\n];\n\napp.get('/api/items', (req, res) => {\n  res.json({ project: \"Decentralized Social Media Platform with Web3 Auth & IPFS\", items, count: items.length });\n});\n\napp.post('/api/items', (req, res) => {\n  const { title, price } = req.body;\n  if (!title || !price) return res.status(400).json({ error: \"Title and price required\" });\n  const newItem = { id: items.length + 1, title, price: parseFloat(price), inStock: true };\n  items.push(newItem);\n  res.status(201).json(newItem);\n});\n\nconst PORT = process.env.PORT || 5000;\napp.listen(PORT, () => console.log(`[SERVER] Decentralized Social Media Platform with Web3 Auth & IPFS running on port ${PORT}`));\n"
